    QThread receiverThread;
    senderThread.start();
    receiverThread.start();
    auto cleanup = qScopeGuard([&] {
        senderThread.quit();
        receiverThread.quit();
        senderThread.wait();
        receiverThread.wait();
    });

    for (int i = 0; i < 200; ++i) {
